function u_c_out = mfun_gfm_voltage_reference(i_c_in, fbk_in, p)
%MFUN_GFM_VOLTAGE_REFERENCE Block voltage_reference of the control system.
%   Generated by motulator_export from the MATLAB port of motulator and called by the
%   MATLAB Function block of the library of motulator, whose folder motulator.setup adds
%   to the MATLAB path. The parameters are the fields of the struct p (from the mask, []
%   as NaN).
i_c = complex_in(i_c_in);
fbk = gfm_feedbacks_unpack(fbk_in);
u_c = gfm_voltage_reference(p.k_c, p.R, i_c, fbk);
u_c_out = complex_out(u_c);
end

function s = gfm_feedbacks_unpack(u)
%GFM_FEEDBACKS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_c', complex(u(1), u(2)), ...
    'u_c', complex(u(3), u(4)), ...
    'u_c_zoh', complex(u(5), u(6)), ...
    'v_c', complex(u(7), u(8)), ...
    'u_g', complex(u(9), u(10)), ...
    'p_g', u(11), ...
    'q_g', u(12), ...
    'theta_c', u(13), ...
    'w_c', u(14));
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end

function u_c_ref = gfm_voltage_reference(k_c, R, i_c_ref, fbk)
%GFM_VOLTAGE_REFERENCE Converter voltage reference from the limited current
%   reference (ObserverBasedGridFormingController.compute_output after the
%   CurrentLimiter), R being the total series resistance estimate.
e_c = k_c*(i_c_ref - fbk.i_c);
u_c_ref = e_c + fbk.v_c + R*fbk.i_c;
end
